entries[38287] = { ["name"] = "Leerer Düsterbräubecher", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nBenötigt Stufe 70\nAnlegen: Erhöht die Angriffskraft um 72.\nBenutzen: Erhöht die Angriffskraft 20 Sek. lang um 278. (2 Min Abklingzeit)\n\"Definitiv nicht halbvoll.\"" }
entries[38288] = { ["name"] = "Düsterbräuhopfen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+38 Intelligenz\nBenötigt Stufe 70\nBenutzen: Erhöht Eure Zaubermacht 20 Sek. lang um 153. (2 Min Abklingzeit)\n\"Nicht sehr erbaulich.\"" }
entries[38289] = { ["name"] = "Corens Glücksmünze", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nBenötigt Stufe 70\nAnlegen: Erhöht Eure Ausweichwertung um 39.\nBenutzen: Erhöht Eure Ausweichwertung 40 Sek. lang um 66. (2 Min Abklingzeit)\n\"Springt von Tischen perfekt ab.\"" }
entries[38290] = { ["name"] = "Tabakspfeife aus Dunkeleisen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+37 Intelligenz\nBenötigt Stufe 70\nBenutzen: Erhöht die Zaubermacht 20 Sek. lang um bis zu 155. (2 Min Abklingzeit)" }
entries[38291] = { ["name"] = "Astrales Mutagen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (5)\nBenutzen: Mutiert ein ausgewähltes Haustier, so lang es an der Seite seines Herrchens bleibt." }
entries[38293] = { ["name"] = "Sonnenstrahlblumen", ["text"] = "Wird beim Aufheben gebunden\nIn Schildhand geführt\n+22 Intelligenz\n+32 Willenskraft\nVerkaufspreis:" }
entries[38294] = { ["name"] = "Astraler Likör", ["text"] = "Herbeigezauberter Gegenstand\nEinzigartig (10)\nBenutzen: Ein süßer, alkoholischer Traum, der auf fleischliche Trinker merkwürdige Effekte haben könnte.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt. (10 Sek. Abklingzeit)" }
entries[38295] = { ["name"] = "Götze der Eiswüsten", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nRelikt\n+13 Beweglichkeit\n+19 Ausdauer\n\nPrismatischer Sockel\n\nKlassen: Schamane , Druide\nAnlegen: Erhöht die kritische Trefferwertung um 8.\nAnlegen: Erhöht die Trefferwertung um 8.\nVerkaufspreis:" }
entries[38300] = { ["name"] = "Verdünnte astrale Essenz", ["text"] = "Herbeigezauberter Gegenstand\nWird beim Aufheben gebunden\nEinzigartig (5)\nBenutzen: Ermöglicht es Euch, 30 Sek. lang geringe Unsichtbarkeit zu entdecken, ohne Hirnschäden zu erleiden... wahrscheinlich.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt." }
entries[38301] = { ["name"] = "D.I.S.C.O.", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Mit Rechtsklick die Party steigen lassen! (5 Min Abklingzeit)\n\"Der internationale Songcontest Oszillator\"" }
entries[38302] = { ["name"] = "Rubinleuchtsignal der Drachenkönigin", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Ruft einen Bezwinger des Wyrmruhtempels herab, um aufzusitzen und in die Schlacht zu reiten. Kann nur im Wyrmruhtempel, der Dracheneiswüste, Galakronds Ruhestätte oder der Serpentine benutzt werden. (30 Sek. Abklingzeit)" }
