entries[38308] = { ["name"] = "Astrale Essenzsphäre", ["text"] = "Herbeigezauberter Gegenstand\nBenutzen: Wirft die Sphäre einem freundlichen Spieler zu. Falls er Platz in seinem Rucksack hat, wird er sie fangen.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt.\n\"Diese extrahierte Seele wurde allein zu Eurem Vergnügen in diese Kugel gequetscht.\"" }
